// Lab 3 of 7 - Return a Calculated Value
class Session05Lab03
{
    public void Run()
    {
        decimal totalHours = AddHours(4m, 3.5m);
        Console.WriteLine($"Total hours: {totalHours}");
    }

    public decimal AddHours(decimal firstHours, decimal secondHours)
