// Lab 4 of 7 - Observe Local Scope
class Session05Lab04
{
    public void Run()
    {
        string message = BuildMessage(8m);
        Console.WriteLine(message);
    }

    public string BuildMessage(decimal hours)
    {
        string localMessage = $"Hours inside the method: {hours}";
        return localMessage;
    }
}

// Add to Program.cs
var session05Lab04 = new Session05Lab04();
session05Lab04.Run();

// Session05Lab05.cs
// Lab 5 of 7 - Name a Variance Calculation
class Session05Lab05
{
    public void Run()
    {
        decimal varianceHours = CalculateVariance(8m, 7.5m);
        Console.WriteLine($"Variance: {varianceHours}");
    }

    public decimal CalculateVariance(decimal recordedHours, decimal scheduledHours)
    {
        decimal difference = recordedHours - scheduledHours;
        return difference;
    }
}

// Add to Program.cs
var session05Lab05 = new Session05Lab05();
session05Lab05.Run();

// Session05Lab06.cs
// Lab 6 of 7 - Name a Classification Decision
class Session05Lab06
{
    public void Run()
    {
        string status = ClassifyVariance(0.5m);
        Console.WriteLine($"Status: {status}");
    }

    public string ClassifyVariance(decimal varianceHours)
    {
        return varianceHours switch
        {
            > 0m => "over schedule",
            < 0m => "under schedule",
            _ => "on schedule"
        };
    }
}

// Add to Program.cs
var session05Lab06 = new Session05Lab06();
session05Lab06.Run();

// Session05Lab07.cs
// Lab 7 of 7 - Combine Calculation and Classification
class Session05Lab07
{
    public void Run()
    {
        decimal varianceHours = CalculateVariance(8m, 7.5m);
        string status = ClassifyVariance(varianceHours);
        Console.WriteLine($"Final variance: {varianceHours}; status: {status}");
    }

    public decimal CalculateVariance(decimal recordedHours, decimal scheduledHours)
    {
        return recordedHours - scheduledHours;
    }

    public string ClassifyVariance(decimal varianceHours)
    {
        return varianceHours switch
        {
            > 0m => "over schedule",
            < 0m => "under schedule",
            _ => "on schedule"
        };
    }
}

// Add to Program.cs
var session05Lab07 = new Session05Lab07();
session05Lab07.Run();
